+    int unsigned i;
+    begin
+      for (i = 0; i < cycles; i++) begin
+        @(negedge clk);
+        avalanche_noise = $urandom_range(0, 1);
+      end
+    end
+  endtask
+
+  // ----------------------------------------------------------------
+  // Main stimulus.
+  // ----------------------------------------------------------------
+  initial begin : main
+    int unsigned i;
+    int unsigned seed;
+    reg [31:0] rdata;
+
+    // Initialize.
+    bus_idle();
+    avalanche_noise = 0;
+    debug_update    = 0;
+    reset_n         = 0;
+
+    // Derive a stable per-run random seed.
+    seed = 32'h1badf00d ^ $urandom();
+    void'($urandom(seed));
+
+    repeat (4) @(posedge clk);
+    reset_n = 1;
+    repeat (4) @(posedge clk);
+
+    // --- Top-level TRNG register pokes.
+    // Read name/version and some defined-but-empty read cases.
+    bus_read(12'h000, rdata); // NAME0
+    bus_read(12'h001, rdata); // NAME1
+    bus_read(12'h002, rdata); // VERSION
+    bus_read(12'h010, rdata); // TRNG_CTRL (empty read)
+    bus_read(12'h011, rdata); // TRNG_STATUS (empty read)
+
+    // Exercise debug mux selections incl. default.
+    bus_write(12'h012, 32'h00000001); // DEBUG_ENTROPY1
+    pulse_debug_update(4);
+    bus_write(12'h012, 32'h00000002); // DEBUG_ENTROPY2
+    pulse_debug_update(4);
+    bus_write(12'h012, 32'h00000003); // DEBUG_MIXER
+    pulse_debug_update(4);
+    bus_write(12'h012, 32'h00000004); // DEBUG_CSPRNG
+    pulse_debug_update(4);
+    bus_write(12'h012, 32'h00000007); // default case
+    pulse_debug_update(2);
+
+    // Force debug update counter to hit both branches quickly.
+    bus_write(12'h013, 32'h00000001);
+    pulse_debug_update(8);
+
+    // Hit TRNG API default/error on write and read.
+    bus_write(12'h0ff, 32'hdeadc0de);
+    bus_read(12'h0fe, rdata);
+
+    // Hit API mux default prefix (top bits not mapped).
+    bus_write(12'hf10, 32'h00000001);
+    bus_read(12'hf11, rdata);
+
+    // --- Configure mixer to enable entropy collection.
+    // MIXER prefix = 0xA. Addresses are 0x10/0x20.
+    bus_write(12'ha20, 32'h00000002); // very small timeout
+    bus_read(12'ha20, rdata);
+    bus_write(12'ha10, 32'h00000001); // enable=1
+    bus_read(12'ha10, rdata);
+    bus_read(12'ha11, rdata); // status
+    bus_write(12'ha7f, 32'h00000000); // default/error
+    bus_read(12'ha7e, rdata);         // default/error
+
+    // --- Configure CSPRNG knobs and read some data.
+    // CSPRNG prefix = 0xB.
+    bus_read(12'hb10, rdata); // ctrl
+    bus_read(12'hb11, rdata); // status
+    bus_write(12'hb40, 32'h00000008); // low rounds
+    bus_read(12'hb40, rdata);
+    bus_write(12'hb41, 32'h00000010); // low blocks
+    bus_write(12'hb42, 32'h00000000); // high blocks
+    bus_read(12'hb41, rdata);
+    bus_read(12'hb42, rdata);
+    bus_write(12'hb7f, 32'h0);        // default/error
+    bus_read(12'hb7e, rdata);         // default/error
+
+    // Let csprng/mixer handshake and generate some fifo output.
+    toggle_noise(20);
+    repeat (200) begin
+      bus_read(12'hb11, rdata);
+      bus_read(12'hb20, rdata); // rnd data (acks)
+      pulse_debug_update(1);    // also acks data path
+      toggle_noise(1);
+    end
+
+    // Exercise cancel paths by disabling CSPRNG for a bit.
+    bus_write(12'hb10, 32'h00000000); // enable=0
+    repeat (20) @(posedge clk);
+    bus_write(12'hb10, 32'h00000001); // enable=1
+    repeat (20) @(posedge clk);
+
+    // Exercise discard behavior mid-flight.
+    bus_write(12'h010, 32'h00000001); // discard=1
+    repeat (10) @(posedge clk);
+    bus_write(12'h010, 32'h00000000); // discard=0
+
+    // Randomized bus traffic to increase statement coverage.
+    for (i = 0; i < 2000; i++) begin
+      reg [11:0] a;
+      reg [31:0] d;
+      a = $urandom();
+      d = $urandom();
+
+      // Bias toward real prefixes/addresses, but include illegal accesses.
+      unique case ($urandom_range(0, 9))
+        0: a = {4'h0, 8'h00 + $urandom_range(0, 3)};  // NAME/VERSION
+        1: a = {4'h0, 8'h10 + $urandom_range(0, 3)};  // TRNG regs
+        2: a = {4'ha, 8'h10 + $urandom_range(0, 1)};  // MIXER ctrl/status
+        3: a = {4'ha, 8'h20};                          // MIXER timeout
+        4: a = {4'hb, 8'h10 + $urandom_range(0, 2)};  // CSPRNG ctrl/status/rnd
+        5: a = {4'hb, 8'h40 + $urandom_range(0, 2)};  // CSPRNG config
+        6: a = {4'h5, 8'h10 + $urandom_range(0, 5)};  // entropy1 (stub) accesses
+        7: a = {4'h6, 8'h10 + $urandom_range(0, 5)};  // entropy2 (stub) accesses
+        default: a = $urandom();                       // fully random/illegal
+      endcase
+
+      if ($urandom_range(0, 1)) begin
+        bus_write(a, d);
+      end else begin
+        bus_read(a, rdata);
+      end
+
+      if ((i % 17) == 0) pulse_debug_update(1);
+      if ((i % 11) == 0) toggle_noise(1);
+    end
+
+    repeat (50) @(posedge clk);
+    $finish;
+  end
+
+endmodule
+
*** End Patch

